function deriveAffectedStocks(title) {
    const t = title.toLowerCase();
    if (/cement/.test(t)) return [
        "LUCK",
        "DGKC",
        "MLCF"
    ];
    if (/fertilizer|urea|dap/.test(t)) return [
        "ENGRO",
        "FFBL",
        "FATIMA"
    ];
    if (/bank| islamic/.test(t)) return [
        "MEBL",
        "BAFL",
        "MCB"
    ];
    if (/oil|gas|energy|crude|petrol/.test(t)) return [
        "OGDC",
        "PPL",
        "PSO"
    ];
    if (/power|electric/.test(t)) return [
        "HUBC",
        "KAPCO",
        "NPL"
    ];
    if (/tech|software|it /.test(t)) return [
        "SYS",
        "AVN",
        "TRSM"
    ];
    if (/imf|dollar|currency|exchange/.test(t)) return [
        "MEBL",
        "HUBC",
        "OGDC"
    ];
    if (/rate|policy|sbp/.test(t)) return [
        "MEBL",
        "HUBC",
        "LUCK"
    ];
    return [];
}
